/* Sina mock exams for 1st year. Built by build/mocks1_build.py. */
window.SINA = window.SINA || { subjects: [], lectures: {} };
SINA.papers = (SINA.papers || []).concat([{"id": "y1-anat1-sina-mock", "subject": "anat1", "title": "Sina mock exam: Anatomy 1", "year": "Practice", "note": "20 new questions written by Sina in the style of the real exam, covering the upper limb and the thorax. One answer per question, each with a short explanation.", "questions": [{"q": "The anatomical position is defined by:", "options": ["Standing upright, palms facing backward", "Lying supine, palms facing the body", "Standing upright, upper limbs by the sides, palms facing forward", "Sitting, head facing forward"], "answer": 2, "why": "Erect, eyes forward, upper limbs at the sides with palms anterior, feet together."}, {"q": "Regarding the clavicle:", "options": ["It is the only bony link between the upper limb and the axial skeleton", "Its lateral end articulates with the manubrium", "Its medial end articulates with the acromion", "It has no medullary cavity and is never fractured"], "answer": 0, "why": "Medial end = sternoclavicular joint; lateral end = acromioclavicular joint. It is the most commonly fractured bone."}, {"q": "The surgical neck of the humerus is closely related to:", "options": ["The axillary nerve and posterior circumflex humeral artery", "The ulnar nerve", "The median nerve", "The radial nerve"], "answer": 0, "why": "Surgical neck fractures endanger the axillary nerve; mid-shaft fractures endanger the radial nerve (radial groove)."}, {"q": "Which muscle is NOT part of the rotator cuff?", "options": ["Teres major", "Infraspinatus", "Subscapularis", "Supraspinatus"], "answer": 0, "why": "SITS: supraspinatus, infraspinatus, teres minor, subscapularis. Teres major is not a cuff muscle."}, {"q": "The deltoid muscle is innervated by:", "options": ["The axillary nerve", "The suprascapular nerve", "The musculocutaneous nerve", "The radial nerve"], "answer": 0, "why": "Axillary nerve (C5-C6) supplies deltoid and teres minor."}, {"q": "The boundaries of the axilla include all of the following EXCEPT:", "options": ["Brachioradialis on the lateral wall", "Serratus anterior on the medial wall", "Pectoralis major in the anterior wall", "Subscapularis in the posterior wall"], "answer": 0, "why": "Lateral wall = intertubercular sulcus of the humerus; brachioradialis is a forearm muscle."}, {"q": "The anterior compartment of the arm contains:", "options": ["Pronator teres and supinator", "Biceps brachii, brachialis and coracobrachialis", "Brachioradialis and anconeus", "Triceps brachii and the radial nerve"], "answer": 1, "why": "Anterior arm = biceps, brachialis, coracobrachialis, all supplied by the musculocutaneous nerve."}, {"q": "The content of the cubital fossa from lateral to medial is:", "options": ["Median nerve, brachial artery, biceps tendon", "Brachial artery, biceps tendon, median nerve", "Biceps tendon, brachial artery, median nerve", "Radial nerve, median nerve, biceps tendon"], "answer": 2, "why": "Lateral to medial: biceps tendon, brachial artery, median nerve (TAN)."}, {"q": "The ulnar nerve passes:", "options": ["Anterior to the lateral epicondyle", "Through the carpal tunnel", "Through the cubital fossa with the median nerve", "Posterior to the medial epicondyle"], "answer": 3, "why": "It runs behind the medial epicondyle (the 'funny bone') and enters the hand through Guyon's canal, not the carpal tunnel."}, {"q": "Which structure passes through the carpal tunnel?", "options": ["Ulnar nerve", "Median nerve", "Ulnar artery", "Palmaris longus tendon"], "answer": 1, "why": "Carpal tunnel: median nerve + 9 tendons (FDS x4, FDP x4, FPL). Ulnar nerve and artery and palmaris longus pass superficial to the flexor retinaculum."}, {"q": "The thenar muscles are mostly innervated by:", "options": ["The recurrent branch of the median nerve", "The radial nerve", "The anterior interosseous nerve", "The deep branch of the ulnar nerve"], "answer": 0, "why": "Abductor pollicis brevis, opponens pollicis and the superficial head of flexor pollicis brevis = recurrent median branch."}, {"q": "The anatomical snuffbox contains:", "options": ["The ulnar artery", "The median nerve", "The basilic vein", "The radial artery"], "answer": 3, "why": "Its floor holds the scaphoid; the radial artery crosses it."}, {"q": "The sternal angle (of Louis):", "options": ["Marks the beginning of the abdominal aorta", "Is the junction between the body and the xiphoid process", "Lies at the level of the T10 vertebra", "Marks the articulation of the 2nd costal cartilage"], "answer": 3, "why": "Manubriosternal joint, level of rib 2 and the T4/T5 disc; arch of the aorta begins and ends there."}, {"q": "True ribs are:", "options": ["Ribs 1 to 10", "Ribs 11 and 12", "Ribs 8 to 10", "Ribs 1 to 7"], "answer": 3, "why": "Ribs 1-7 attach directly to the sternum by their own costal cartilage; 8-10 are false; 11-12 are floating."}, {"q": "The intercostal neurovascular bundle runs:", "options": ["Between the external intercostal muscle and the skin", "In the middle of the intercostal space", "In the costal groove, along the inferior border of the rib above", "Along the upper border of the rib below"], "answer": 2, "why": "VAN (vein, artery, nerve) from above downward, in the costal groove; needles are inserted just above the rib below."}, {"q": "The diaphragm is innervated by:", "options": ["The vagus nerve", "The sympathetic trunk", "The phrenic nerve (C3-C5)", "The intercostal nerves only"], "answer": 2, "why": "'C3, 4, 5 keeps the diaphragm alive' (motor supply)."}, {"q": "The inferior vena cava passes through the diaphragm at the level of:", "options": ["L2", "T10", "T8", "T12"], "answer": 2, "why": "IVC T8, oesophagus T10, aorta T12."}, {"q": "The right coronary artery usually supplies:", "options": ["The sinoatrial and atrioventricular nodes", "The anterior two-thirds of the interventricular septum", "The left atrium only", "Mainly the left ventricle"], "answer": 0, "why": "In most people the RCA supplies the SA (≈60%) and AV (≈80%) nodes; the LAD supplies the anterior septum."}, {"q": "The right lung has:", "options": ["Three lobes and one fissure", "Two lobes and one fissure", "Two lobes and a cardiac notch", "Three lobes and two fissures"], "answer": 3, "why": "Right: superior, middle, inferior lobes, oblique + horizontal fissures. Left: two lobes, cardiac notch and lingula."}, {"q": "The superior mediastinum contains:", "options": ["The heart and pericardium", "The arch of the aorta, the thymus and the brachiocephalic veins", "The inferior vena cava", "The descending thoracic aorta below T4 only"], "answer": 1, "why": "Superior mediastinum (above the T4/T5 plane): thymus, great veins, aortic arch and its branches, trachea, oesophagus, nerves."}]}, {"id": "y1-anat2-sina-mock", "subject": "anat2", "title": "Sina mock exam: Anatomy 2", "year": "Practice", "note": "20 new questions written by Sina in the style of the real exam, covering the abdomen, pelvis and perineum. One answer per question, each with a short explanation.", "questions": [{"q": "The inguinal canal:", "options": ["Has the external oblique aponeurosis as its posterior wall", "Lies below the inguinal ligament", "Runs from the deep inguinal ring to the superficial ring, above and parallel to the inguinal ligament", "Contains the femoral artery"], "answer": 2, "why": "Anterior wall = external oblique aponeurosis; posterior wall = transversalis fascia (+ conjoint tendon); floor = inguinal ligament."}, {"q": "An indirect inguinal hernia:", "options": ["Leaves the abdomen through the deep inguinal ring, lateral to the inferior epigastric vessels", "Is always acquired in elderly men", "Passes below the inguinal ligament", "Passes through Hesselbach's triangle"], "answer": 0, "why": "Indirect = lateral to the inferior epigastric vessels through the deep ring; direct = medial, through Hesselbach's triangle."}, {"q": "The linea alba is formed by:", "options": ["The tendinous intersections of rectus abdominis", "The transversalis fascia", "The fusion of the aponeuroses of the flat abdominal muscles in the midline", "The inguinal ligament"], "answer": 2, "why": "The aponeuroses of external oblique, internal oblique and transversus abdominis meet in the midline."}, {"q": "The lesser curvature of the stomach is supplied by:", "options": ["The right and left gastroepiploic arteries", "The superior mesenteric artery", "The right and left gastric arteries", "The short gastric arteries"], "answer": 2, "why": "Lesser curvature: left gastric (coeliac) + right gastric (common hepatic). Greater curvature: gastroepiploic arteries."}, {"q": "The oesophagus crosses the diaphragm at the level of:", "options": ["T8", "T10", "L1", "T12"], "answer": 1, "why": "Oesophageal hiatus at T10, with the vagal trunks."}, {"q": "The duodenojejunal flexure is held by:", "options": ["The falciform ligament", "The gastrosplenic ligament", "The suspensory ligament of the duodenum (ligament of Treitz)", "The round ligament"], "answer": 2, "why": "The ligament of Treitz marks the end of the duodenum and is the landmark between upper and lower GI bleeding."}, {"q": "Compared with the ileum, the jejunum has:", "options": ["More Peyer's patches", "More arterial arcades and shorter vasa recta", "A smaller diameter and fat-laden mesentery", "Thicker walls, more plicae circulares and longer vasa recta"], "answer": 3, "why": "Jejunum: wider, thicker, more circular folds, few arcades, long vasa recta. Ileum: Peyer's patches, many arcades."}, {"q": "Features that distinguish the colon from the small intestine include:", "options": ["A complete outer longitudinal muscle layer", "Taeniae coli, haustra and epiploic appendages", "Plicae circulares", "Villi and Peyer's patches"], "answer": 1, "why": "The three taeniae coli, haustrations and appendices epiploicae identify the large bowel."}, {"q": "The appendix is usually located by following:", "options": ["The falciform ligament", "The taeniae coli of the caecum to where they converge", "The ileocolic vein upward", "The sigmoid mesocolon"], "answer": 1, "why": "The taeniae converge on the base of the appendix (McBurney's point on the surface)."}, {"q": "The hepatic portal vein is formed by the union of:", "options": ["The splenic vein and the superior mesenteric vein behind the neck of the pancreas", "The left and right hepatic veins", "The inferior vena cava and the renal veins", "The inferior mesenteric vein and the left gastric vein only"], "answer": 0, "why": "SMV + splenic vein behind the pancreatic neck; the IMV usually drains into the splenic vein."}, {"q": "The hepatoduodenal ligament (free edge of the lesser omentum) contains:", "options": ["The inferior vena cava", "The portal vein, the proper hepatic artery and the common bile duct", "The hepatic veins", "The splenic artery"], "answer": 1, "why": "The portal triad: bile duct (right, anterior), hepatic artery (left, anterior), portal vein (posterior)."}, {"q": "Calot's triangle (cystohepatic triangle) is bounded by:", "options": ["The common bile duct, the duodenum and the pancreas", "The portal vein, the IVC and the caudate lobe", "The left and right hepatic ducts and the gallbladder", "The cystic duct, the common hepatic duct and the inferior surface of the liver"], "answer": 3, "why": "It contains the cystic artery, which must be identified during cholecystectomy."}, {"q": "The common bile duct usually opens into:", "options": ["The second (descending) part of the duodenum at the major duodenal papilla", "The jejunum", "The third part of the duodenum", "The first part of the duodenum"], "answer": 0, "why": "With the main pancreatic duct, through the hepatopancreatic ampulla (of Vater) controlled by the sphincter of Oddi."}, {"q": "The pancreas is:", "options": ["Mostly retroperitoneal, except the tail which reaches the splenic hilum", "Supplied only by the superior mesenteric artery", "Located in the right iliac fossa", "Entirely intraperitoneal"], "answer": 0, "why": "Head in the duodenal C-loop, tail in the splenorenal ligament; supplied by splenic and pancreaticoduodenal arteries."}, {"q": "The spleen lies against ribs:", "options": ["11 and 12 on the right", "5 to 7 on the left", "9 to 11 on the left", "1 to 3 on the right"], "answer": 2, "why": "Spleen: '1, 3, 5, 7, 9, 11' — 1 × 3 × 5 inches, 7 oz, ribs 9 to 11 on the left."}, {"q": "The coeliac trunk arises at the level of:", "options": ["T8", "T12", "L4", "L3"], "answer": 1, "why": "Coeliac T12, SMA L1, renal arteries L1-L2, IMA L3, bifurcation L4."}, {"q": "The branches of the coeliac trunk are:", "options": ["Left gastric, splenic and common hepatic arteries", "Left colic, sigmoid and superior rectal arteries", "Superior mesenteric and inferior mesenteric arteries", "Right gastric, splenic and ileocolic arteries"], "answer": 0, "why": "Coeliac trunk = left gastric, splenic, common hepatic (foregut)."}, {"q": "Parasympathetic supply to the descending colon and rectum comes from:", "options": ["The greater splanchnic nerve", "The vagus nerve", "The pelvic splanchnic nerves (S2-S4)", "The phrenic nerve"], "answer": 2, "why": "The vagus reaches about two-thirds of the transverse colon; beyond that, pelvic splanchnic nerves (S2-S4)."}, {"q": "The internal iliac artery supplies mainly:", "options": ["The kidneys", "The pelvic organs, perineum and gluteal region", "The lower limb", "The anterior abdominal wall above the umbilicus"], "answer": 1, "why": "The external iliac continues as the femoral artery to the lower limb."}, {"q": "The levator ani is composed of:", "options": ["Obturator internus and piriformis", "The external anal sphincter only", "Ischiocavernosus and bulbospongiosus", "Pubococcygeus, puborectalis and iliococcygeus"], "answer": 3, "why": "With coccygeus, the levator ani forms the pelvic diaphragm; puborectalis keeps the anorectal angle."}]}, {"id": "y1-physio1-sina-mock", "subject": "physio1", "title": "Sina mock exam: Physiology", "year": "Practice", "note": "20 new questions written by Sina in the style of the real exam, covering cardiovascular, respiratory, digestive and endocrine physiology. One answer per question, each with a short explanation.", "questions": [{"q": "The normal pacemaker of the heart is:", "options": ["The sinoatrial node", "The bundle of His", "The Purkinje fibres", "The atrioventricular node"], "answer": 0, "why": "The SA node has the fastest intrinsic rate (≈60-100/min) and sets the rhythm."}, {"q": "The plateau phase (phase 2) of the ventricular action potential is mainly due to:", "options": ["Fast Na+ entry", "Cl- entry", "Slow Ca2+ entry through L-type channels balanced by K+ exit", "Na+/K+ ATPase activity"], "answer": 2, "why": "L-type Ca2+ influx balances K+ efflux, prolonging the action potential and the refractory period."}, {"q": "Cardiac output equals:", "options": ["End-diastolic volume − heart rate", "Stroke volume / heart rate", "Mean arterial pressure × heart rate", "Heart rate × stroke volume"], "answer": 3, "why": "CO = HR × SV (≈ 70 × 70 mL ≈ 5 L/min)."}, {"q": "According to the Frank-Starling law, stroke volume increases when:", "options": ["End-diastolic volume (preload) increases", "Ventricular filling decreases", "Heart rate increases above 180/min", "Afterload increases"], "answer": 0, "why": "Greater stretch of the myocardium leads to a stronger contraction, within physiological limits."}, {"q": "During isovolumetric contraction:", "options": ["The aortic valve is open", "Ventricular volume falls quickly", "The mitral valve is open", "All valves are closed and ventricular pressure rises"], "answer": 3, "why": "Between closure of the AV valves (S1) and opening of the semilunar valves."}, {"q": "On the ECG, the QRS complex represents:", "options": ["Ventricular repolarisation", "Atrial depolarisation", "Ventricular depolarisation", "Conduction through the AV node only"], "answer": 2, "why": "P = atrial depolarisation, QRS = ventricular depolarisation, T = ventricular repolarisation."}, {"q": "A normal PR interval is:", "options": ["0.12-0.20 s", "More than 0.44 s", "0.04-0.08 s", "0.30-0.40 s"], "answer": 0, "why": "PR > 0.20 s = first-degree AV block."}, {"q": "Vital capacity equals:", "options": ["Residual volume + tidal volume", "Functional residual capacity − tidal volume", "Tidal volume + inspiratory reserve volume + expiratory reserve volume", "Total lung capacity + residual volume"], "answer": 2, "why": "VC = TV + IRV + ERV; TLC = VC + RV."}, {"q": "Which volume cannot be measured by simple spirometry?", "options": ["Tidal volume", "Expiratory reserve volume", "Residual volume", "Inspiratory reserve volume"], "answer": 2, "why": "Residual volume (and so FRC and TLC) needs helium dilution, nitrogen washout or plethysmography."}, {"q": "Hypoxic pulmonary vasoconstriction:", "options": ["Happens in systemic arteries as well", "Increases ventilation-perfusion mismatch", "Dilates vessels in poorly ventilated areas", "Diverts blood away from poorly ventilated alveoli"], "answer": 3, "why": "Unlike systemic vessels, pulmonary vessels constrict in hypoxia, matching perfusion to ventilation."}, {"q": "The pulmonary circulation is a:", "options": ["Low-flow system receiving 10% of the cardiac output", "High-pressure, high-resistance system", "System with a mean pressure of about 90 mmHg", "Low-pressure, low-resistance system"], "answer": 3, "why": "Mean pulmonary artery pressure ≈ 15 mmHg; it receives the whole right ventricular output."}, {"q": "The swallowing reflex centre is located in:", "options": ["The cerebellum", "The spinal cord at C5", "The medulla oblongata (brainstem)", "The cerebral cortex"], "answer": 2, "why": "The oral phase is voluntary; the pharyngeal and oesophageal phases are reflex, controlled by the medulla."}, {"q": "Hydrochloric acid in the stomach is secreted by:", "options": ["G cells", "Parietal cells", "Chief cells", "Mucous neck cells"], "answer": 1, "why": "Parietal (oxyntic) cells secrete HCl and intrinsic factor; chief cells secrete pepsinogen; G cells secrete gastrin."}, {"q": "Which substance does NOT stimulate acid secretion by parietal cells?", "options": ["Histamine", "Acetylcholine", "Gastrin", "Somatostatin"], "answer": 3, "why": "Somatostatin inhibits acid secretion; ACh, gastrin and histamine stimulate it."}, {"q": "Secretin mainly stimulates:", "options": ["Pancreatic enzyme secretion", "Gallbladder contraction", "Gastric acid secretion", "Pancreatic bicarbonate secretion"], "answer": 3, "why": "Secretin (from S cells, released by acid in the duodenum) causes bicarbonate-rich pancreatic juice; CCK drives enzymes and gallbladder contraction."}, {"q": "The migrating motor complex (MMC):", "options": ["Is triggered by gastrin only", "Happens during fasting and sweeps residue through the small bowel", "Is a colonic movement", "Happens mainly after meals"], "answer": 1, "why": "MMCs are fasting 'housekeeper' waves, linked to motilin."}, {"q": "Most water absorption in the gut happens in:", "options": ["The rectum", "The stomach", "The small intestine", "The colon"], "answer": 2, "why": "About 80% of water is absorbed in the small intestine; the colon absorbs most of the rest."}, {"q": "Glucose is absorbed across the apical membrane of the enterocyte by:", "options": ["Endocytosis", "GLUT5", "Simple diffusion", "SGLT1, coupled to Na+"], "answer": 3, "why": "SGLT1 (Na+-glucose cotransport) apically; GLUT2 basolaterally. Fructose uses GLUT5."}, {"q": "Hormones secreted by the anterior pituitary include:", "options": ["Cortisol and aldosterone", "T3 and T4", "ADH and oxytocin", "TSH, ACTH, GH, prolactin, FSH and LH"], "answer": 3, "why": "ADH and oxytocin are made in the hypothalamus and released from the posterior pituitary."}, {"q": "Most circulating thyroid hormone is:", "options": ["Free T4", "Free T3", "T4 bound to plasma proteins (mainly TBG)", "Reverse T3"], "answer": 2, "why": "Over 99% is protein-bound; T4 is the main secreted form and is converted to the active T3 in tissues."}]}, {"id": "y1-biochem1-sina-mock", "subject": "biochem1", "title": "Sina mock exam: Biochemistry", "year": "Practice", "note": "20 new questions written by Sina in the style of the real exam, covering biomolecules, enzymes and metabolism. One answer per question, each with a short explanation.", "questions": [{"q": "Which amino acid has no chiral (asymmetric) carbon?", "options": ["Leucine", "Serine", "Glycine", "Alanine"], "answer": 2, "why": "Glycine's side chain is H, so its α-carbon carries two identical groups."}, {"q": "Amino acids found in human proteins are of the:", "options": ["β series", "Racemic mixture", "D series", "L series"], "answer": 3, "why": "Proteins are made of L-α-amino acids."}, {"q": "At its isoelectric point (pI), an amino acid:", "options": ["Carries a net negative charge", "Is fully protonated", "Carries no net charge", "Carries a net positive charge"], "answer": 2, "why": "At the pI the zwitterion has zero net charge and does not move in an electric field."}, {"q": "The peptide bond:", "options": ["Rotates freely", "Is planar, with partial double-bond character", "Is a hydrogen bond", "Links two side chains"], "answer": 1, "why": "Resonance gives the C-N bond partial double-bond character, so it is rigid and usually trans."}, {"q": "The α-helix and β-pleated sheet are examples of:", "options": ["Secondary structure stabilised by hydrogen bonds between backbone groups", "Disulfide bonds", "Quaternary structure", "Primary structure"], "answer": 0, "why": "Secondary structure = local folding held by H-bonds between C=O and N-H of the backbone."}, {"q": "The Michaelis constant (Km) is:", "options": ["The substrate concentration that gives half of Vmax", "Raised by a non-competitive inhibitor", "The maximum rate of the reaction", "Independent of the substrate"], "answer": 0, "why": "Low Km = high affinity. Competitive inhibitors raise apparent Km; non-competitive inhibitors lower Vmax."}, {"q": "A competitive inhibitor:", "options": ["Raises the apparent Km and leaves Vmax unchanged", "Cannot be overcome by excess substrate", "Lowers Vmax and leaves Km unchanged", "Binds only the enzyme-substrate complex"], "answer": 0, "why": "It competes for the active site; enough substrate restores Vmax."}, {"q": "Glucose and galactose are:", "options": ["Anomers", "Ketoses", "Epimers at carbon 4", "Enantiomers"], "answer": 2, "why": "They differ only in the configuration at C-4."}, {"q": "Sucrose is made of:", "options": ["Galactose + fructose", "Glucose + fructose", "Glucose + galactose", "Glucose + glucose"], "answer": 1, "why": "Lactose = glucose + galactose; maltose = glucose + glucose."}, {"q": "Glycogen differs from amylose because it:", "options": ["Has only α(1→4) bonds", "Contains β(1→4) bonds", "Is more highly branched with α(1→6) bonds", "Is a plant polysaccharide"], "answer": 2, "why": "Glycogen branches every 8-12 residues, more often than amylopectin."}, {"q": "Essential fatty acids for humans include:", "options": ["Stearic acid", "Palmitic acid", "Linoleic and α-linolenic acids", "Oleic acid"], "answer": 2, "why": "Humans cannot insert double bonds beyond C-9, so ω-6 linoleic and ω-3 α-linolenic acids must come from the diet."}, {"q": "Which lipoprotein carries most cholesterol to peripheral tissues?", "options": ["Chylomicrons", "HDL", "LDL", "VLDL"], "answer": 2, "why": "LDL delivers cholesterol to tissues; HDL brings it back to the liver (reverse transport)."}, {"q": "In DNA, adenine pairs with:", "options": ["Guanine by three hydrogen bonds", "Thymine by two hydrogen bonds", "Cytosine by two hydrogen bonds", "Uracil"], "answer": 1, "why": "A=T (2 H-bonds), G≡C (3 H-bonds). In RNA, uracil replaces thymine."}, {"q": "The rate-limiting enzyme of glycolysis is:", "options": ["Aldolase", "Hexokinase", "Phosphofructokinase-1", "Pyruvate kinase"], "answer": 2, "why": "PFK-1 is activated by AMP and fructose-2,6-bisphosphate and inhibited by ATP and citrate."}, {"q": "Under anaerobic conditions, pyruvate in muscle is converted to:", "options": ["Acetyl-CoA", "Lactate, which regenerates NAD+", "Ethanol", "Oxaloacetate"], "answer": 1, "why": "Lactate dehydrogenase regenerates NAD+ so glycolysis can continue."}, {"q": "Gluconeogenesis mainly happens in:", "options": ["The liver (and the renal cortex)", "The brain", "Skeletal muscle", "Red blood cells"], "answer": 0, "why": "Muscle lacks glucose-6-phosphatase and cannot release free glucose."}, {"q": "β-oxidation of fatty acids takes place in:", "options": ["The mitochondrial matrix", "The nucleus", "The cytosol", "The endoplasmic reticulum"], "answer": 0, "why": "Long-chain fatty acids enter via the carnitine shuttle; synthesis happens in the cytosol."}, {"q": "The rate-limiting enzyme of cholesterol synthesis is:", "options": ["Acetyl-CoA carboxylase", "Carnitine palmitoyltransferase I", "HMG-CoA reductase", "Lipoprotein lipase"], "answer": 2, "why": "It is the target of statins."}, {"q": "The urea cycle takes place in:", "options": ["The kidney only", "Muscle", "The liver, partly in mitochondria and partly in the cytosol", "The brain"], "answer": 2, "why": "Carbamoyl phosphate and citrulline form in mitochondria; the rest of the cycle is cytosolic."}, {"q": "Transamination reactions require the coenzyme:", "options": ["Coenzyme A", "Thiamine pyrophosphate", "Biotin", "Pyridoxal phosphate (vitamin B6)"], "answer": 3, "why": "ALT and AST use pyridoxal phosphate."}]}, {"id": "y1-immuno1-sina-mock", "subject": "immuno1", "title": "Sina mock exam: Immunology", "year": "Practice", "note": "20 new questions written by Sina in the style of the real exam, covering lymphoid organs, antibodies, complement, innate immunity, MHC and lab tests. One answer per question, each with a short explanation.", "questions": [{"q": "Primary (central) lymphoid organs are:", "options": ["Tonsils and Peyer's patches", "Bone marrow and thymus", "Spleen and lymph nodes", "Liver and spleen"], "answer": 1, "why": "Lymphocytes are made and selected in the bone marrow (B) and thymus (T); they meet antigen in secondary organs."}, {"q": "Positive selection of T cells in the thymus keeps cells that:", "options": ["Express both CD4 and CD8 at the end", "Do not bind MHC at all", "Bind self-MHC with moderate affinity", "Bind self-antigens strongly"], "answer": 2, "why": "Positive selection (cortex) = MHC restriction; negative selection (medulla) removes strongly self-reactive cells."}, {"q": "Which cell is the main antigen-presenting cell for naive T cells?", "options": ["Erythrocyte", "Neutrophil", "Dendritic cell", "Eosinophil"], "answer": 2, "why": "Dendritic cells are the most effective activators of naive T cells."}, {"q": "An epitope is:", "options": ["The part of an antigen recognised by an antibody or T-cell receptor", "The whole antigen molecule", "A carrier protein", "The constant region of an antibody"], "answer": 0, "why": "Also called the antigenic determinant; a hapten needs a carrier to be immunogenic."}, {"q": "The immunoglobulin that crosses the placenta is:", "options": ["IgG", "IgE", "IgA", "IgM"], "answer": 0, "why": "IgG is carried across by the neonatal Fc receptor (FcRn)."}, {"q": "The first antibody produced in a primary immune response is:", "options": ["IgG", "IgM", "IgD", "IgE"], "answer": 1, "why": "IgM (pentamer) dominates the primary response; IgG dominates the secondary response."}, {"q": "Secretory IgA is:", "options": ["A pentamer", "The main antibody in allergy", "A dimer with a J chain and secretory component", "Found mostly in serum"], "answer": 2, "why": "It protects mucosal surfaces and is present in breast milk."}, {"q": "The classical complement pathway is started by:", "options": ["Factor B", "Spontaneous hydrolysis of C3", "C1q binding to antigen-antibody complexes", "Mannose-binding lectin"], "answer": 2, "why": "Classical = antibody (IgM, IgG); lectin = MBL; alternative = spontaneous C3 activation on surfaces."}, {"q": "The membrane attack complex is formed by:", "options": ["C4b2a", "C1q, C1r, C1s", "C5b-C9", "C3a and C5a"], "answer": 2, "why": "C5b, C6, C7, C8 and multiple C9 form a pore."}, {"q": "Which complement fragment is the main opsonin?", "options": ["C9", "C3b", "C2a", "C5a"], "answer": 1, "why": "C3b coats microbes for phagocytosis; C3a and C5a are anaphylatoxins and chemoattractants."}, {"q": "Pattern recognition receptors such as Toll-like receptors recognise:", "options": ["Only self-antigens", "Antibodies", "Conserved microbial molecules (PAMPs)", "Specific peptide-MHC complexes"], "answer": 2, "why": "They belong to innate immunity, e.g. TLR4 recognises LPS."}, {"q": "The first leukocytes to arrive at a site of acute inflammation are usually:", "options": ["Lymphocytes", "Plasma cells", "Neutrophils", "Eosinophils"], "answer": 2, "why": "Neutrophils dominate in the first 6-24 hours, then monocytes and macrophages."}, {"q": "The correct order of leukocyte extravasation is:", "options": ["Adhesion, rolling, transmigration", "Chemotaxis, rolling, phagocytosis", "Transmigration, rolling, adhesion", "Rolling (selectins), firm adhesion (integrins), transmigration, chemotaxis"], "answer": 3, "why": "Selectins drive rolling, integrins (LFA-1 binding ICAM-1) drive firm adhesion, then diapedesis via PECAM-1."}, {"q": "The respiratory (oxidative) burst of phagocytes depends on:", "options": ["Perforin", "NADPH oxidase", "Complement C9", "Lysozyme"], "answer": 1, "why": "Its absence causes chronic granulomatous disease."}, {"q": "MHC class I molecules:", "options": ["Present extracellular peptides to CD4+ T cells", "Are found only on antigen-presenting cells", "Are absent from all human cells", "Are found on all nucleated cells and present peptides to CD8+ T cells"], "answer": 3, "why": "Class I presents cytosolic (endogenous) peptides to CD8+; class II (APCs) presents exogenous peptides to CD4+."}, {"q": "Natural killer (NK) cells kill cells that:", "options": ["Carry antibody on their surface only", "Have lost or reduced MHC class I ('missing self')", "Express high levels of MHC class I", "Are B lymphocytes"], "answer": 1, "why": "Loss of MHC I removes the inhibitory signal; NK cells also kill antibody-coated cells by ADCC."}, {"q": "Immunological memory is a feature of:", "options": ["Neutrophils", "Complement only", "Innate immunity", "Adaptive immunity"], "answer": 3, "why": "Memory B and T cells give faster, stronger secondary responses; this is the basis of vaccination."}, {"q": "Th1 cells mainly produce:", "options": ["IL-4 and IL-5", "IFN-γ, which activates macrophages", "IL-17 only", "IgE"], "answer": 1, "why": "Th1: IFN-γ (intracellular microbes); Th2: IL-4, IL-5, IL-13 (helminths, allergy); Th17: IL-17 (extracellular bacteria, fungi)."}, {"q": "In an ELISA, the signal is produced by:", "options": ["Agglutination of red cells", "Complement lysis", "An enzyme linked to an antibody acting on a substrate", "A radioactive label"], "answer": 2, "why": "Enzyme-linked immunosorbent assay: the enzyme turns a substrate into a coloured product."}, {"q": "A direct Coombs test detects:", "options": ["Free antibodies in the patient's serum", "Antibodies or complement already bound to the patient's red cells", "Antinuclear antibodies", "ABO blood group only"], "answer": 1, "why": "The indirect Coombs test detects free antibodies in serum (e.g. antenatal screening, cross-matching)."}]}, {"id": "y1-hemato1-sina-mock", "subject": "hemato1", "title": "Sina mock exam: Hematology", "year": "Practice", "note": "20 new questions written by Sina in the style of the real exam, covering red cells, iron and vitamins, white cells, haemostasis and transfusion. One answer per question, each with a short explanation.", "questions": [{"q": "In adults, haematopoiesis normally takes place in:", "options": ["The yolk sac", "The red bone marrow of the axial skeleton and proximal long bones", "The lymph nodes", "The liver and spleen"], "answer": 1, "why": "Yolk sac → liver/spleen → bone marrow; in adults it is restricted to flat bones, vertebrae and proximal femur and humerus."}, {"q": "The main hormone that drives erythropoiesis is:", "options": ["Interleukin-5", "Thrombopoietin", "G-CSF", "Erythropoietin, produced mainly by the kidney"], "answer": 3, "why": "Peritubular cells of the kidney release EPO in response to hypoxia."}, {"q": "The normal life span of a red blood cell is about:", "options": ["120 days", "30 days", "1 year", "10 days"], "answer": 0, "why": "Old red cells are removed by macrophages, mainly in the spleen."}, {"q": "Dietary iron is absorbed mainly in:", "options": ["The colon", "The stomach", "The duodenum and upper jejunum", "The terminal ileum"], "answer": 2, "why": "Absorption is regulated by hepcidin, which blocks ferroportin. Vitamin B12 is absorbed in the terminal ileum."}, {"q": "The best single test to confirm iron deficiency is:", "options": ["Serum iron", "MCHC", "Reticulocyte count", "Serum ferritin (low)"], "answer": 3, "why": "Low ferritin reflects depleted stores; ferritin rises with inflammation, so it can be falsely normal."}, {"q": "Vitamin B12 absorption requires:", "options": ["Transferrin", "Intrinsic factor from gastric parietal cells, with absorption in the terminal ileum", "Hydrochloric acid only", "Bile salts"], "answer": 1, "why": "Pernicious anaemia: autoantibodies against parietal cells or intrinsic factor."}, {"q": "Folate or vitamin B12 deficiency causes:", "options": ["Haemolytic anaemia with spherocytes", "Microcytic hypochromic anaemia", "Polycythaemia", "Megaloblastic macrocytic anaemia with hypersegmented neutrophils"], "answer": 3, "why": "Impaired DNA synthesis delays nuclear maturation."}, {"q": "Mean corpuscular volume (MCV) is:", "options": ["White cell count × platelets", "Haemoglobin / haematocrit", "Haemoglobin / red cell count", "Haematocrit / red cell count"], "answer": 3, "why": "MCV = Hct / RBC (normal ≈ 80-100 fL); MCH = Hb / RBC; MCHC = Hb / Hct."}, {"q": "A microcytic anaemia (low MCV) is typical of:", "options": ["Hypothyroidism", "Alcohol excess", "Iron deficiency and thalassaemia", "Vitamin B12 deficiency"], "answer": 2, "why": "Microcytic: iron deficiency, thalassaemia, anaemia of chronic disease (sometimes), sideroblastic anaemia."}, {"q": "A high reticulocyte count in an anaemic patient suggests:", "options": ["Iron deficiency before treatment", "Haemolysis or acute blood loss (regenerative anaemia)", "Bone marrow failure", "Aplastic anaemia"], "answer": 1, "why": "The marrow responds normally by releasing young red cells."}, {"q": "The most abundant white blood cell in adult blood is:", "options": ["Monocyte", "Lymphocyte", "Neutrophil", "Eosinophil"], "answer": 2, "why": "Neutrophils ≈ 50-70%, lymphocytes ≈ 20-40%."}, {"q": "Eosinophilia is classically seen in:", "options": ["Parasitic (helminth) infections and allergy", "Bacterial pneumonia", "Iron deficiency", "Viral hepatitis"], "answer": 0, "why": "Eosinophils fight helminths and take part in allergic reactions."}, {"q": "Primary haemostasis involves:", "options": ["Fibrinolysis", "Formation of a fibrin clot", "Activation of factor X only", "Vasoconstriction and formation of the platelet plug"], "answer": 3, "why": "Platelets adhere (vWF binding GPIb), become activated and aggregate (fibrinogen bridging GPIIb/IIIa)."}, {"q": "Von Willebrand factor:", "options": ["Breaks down fibrin", "Is made by red cells", "Links platelets to exposed collagen and carries factor VIII", "Is a vitamin K-dependent factor"], "answer": 2, "why": "It is made by endothelial cells and megakaryocytes."}, {"q": "The vitamin K-dependent coagulation factors are:", "options": ["I, V, VIII, XIII", "III and IV", "XI, XII only", "II, VII, IX, X (and proteins C and S)"], "answer": 3, "why": "Warfarin blocks their γ-carboxylation."}, {"q": "The prothrombin time (PT/INR) mainly explores:", "options": ["The extrinsic and common pathways (VII, X, V, II, fibrinogen)", "The intrinsic pathway (VIII, IX, XI, XII)", "Fibrinolysis only", "Platelet function"], "answer": 0, "why": "aPTT explores the intrinsic + common pathways and is prolonged in haemophilia A and B."}, {"q": "Haemophilia A is due to a deficiency of:", "options": ["Factor VIII", "Factor IX", "Factor VII", "Von Willebrand factor"], "answer": 0, "why": "X-linked recessive; haemophilia B = factor IX."}, {"q": "Thrombocytopenia is defined as a platelet count below:", "options": ["400 × 10⁹/L", "50 × 10⁹/L only", "1000 × 10⁹/L", "150 × 10⁹/L"], "answer": 3, "why": "Normal range ≈ 150-400 × 10⁹/L; spontaneous bleeding usually appears well below 20-30 × 10⁹/L."}, {"q": "A person with blood group O:", "options": ["Has A and B antigens on red cells", "Has no antibodies", "Has anti-A and anti-B antibodies in plasma", "Is the universal recipient"], "answer": 2, "why": "Group O red cells are the universal donor cells; AB is the universal plasma donor and red-cell recipient."}, {"q": "Splenomegaly can cause:", "options": ["Raised platelet count in all cases", "Iron overload", "Hypersplenism with cytopenias (pooling and destruction of blood cells)", "Polycythaemia"], "answer": 2, "why": "An enlarged spleen sequesters platelets and red cells."}]}, {"id": "y1-embryo1-sina-mock", "subject": "embryo1", "title": "Sina mock exam: Embryology", "year": "Practice", "note": "20 new questions written by Sina in the style of the real exam, covering gametogenesis to the fetal period and the digestive system. One answer per question, each with a short explanation.", "questions": [{"q": "Meiosis I in the human oocyte is arrested at:", "options": ["Telophase II", "Metaphase II until puberty", "Anaphase I", "Prophase I (diplotene) until shortly before ovulation"], "answer": 3, "why": "Primary oocytes stay in prophase I from fetal life; the secondary oocyte then arrests in metaphase II until fertilisation."}, {"q": "Spermatogenesis produces from one primary spermatocyte:", "options": ["Eight spermatids", "Two spermatids and two polar bodies", "One spermatozoon", "Four spermatids"], "answer": 3, "why": "Oogenesis gives one ovum and polar bodies."}, {"q": "Fertilisation usually takes place in:", "options": ["The ovary", "The ampulla of the uterine tube", "The uterine cavity", "The cervix"], "answer": 1, "why": "Implantation normally occurs in the posterior wall of the uterine body."}, {"q": "The cortical (zona) reaction:", "options": ["Allows several sperm to enter", "Triggers the acrosome reaction", "Starts capacitation", "Prevents polyspermy"], "answer": 3, "why": "Cortical granule enzymes modify the zona pellucida."}, {"q": "Implantation usually begins around:", "options": ["Day 21", "Day 14", "Day 6-7 after fertilisation", "Day 1 after fertilisation"], "answer": 2, "why": "The blastocyst hatches from the zona and attaches to the endometrium."}, {"q": "The syncytiotrophoblast secretes:", "options": ["hCG (human chorionic gonadotropin)", "Prolactin", "Oxytocin", "FSH"], "answer": 0, "why": "hCG maintains the corpus luteum and is the basis of pregnancy tests."}, {"q": "Gastrulation (week 3) forms:", "options": ["The placenta", "The bilaminar disc", "The neural tube only", "The three germ layers via the primitive streak"], "answer": 3, "why": "Epiblast cells migrate through the primitive streak to form endoderm and mesoderm; the remaining epiblast becomes ectoderm."}, {"q": "The notochord induces:", "options": ["The liver", "The neural plate from the overlying ectoderm", "The somites to become blood", "The heart"], "answer": 1, "why": "Neurulation follows: neural folds form the neural tube."}, {"q": "Which derives from the neural crest?", "options": ["Melanocytes and dorsal root ganglia", "The liver", "Skeletal muscle", "The spinal cord"], "answer": 0, "why": "Neural crest also forms the adrenal medulla, Schwann cells, and much of the facial skeleton."}, {"q": "Failure of the posterior neuropore to close leads to:", "options": ["Cleft lip", "Anencephaly", "Spina bifida", "Hydrocele"], "answer": 2, "why": "Anterior neuropore failure gives anencephaly. Folic acid lowers the risk."}, {"q": "Somites give rise to:", "options": ["The heart", "The gut epithelium", "Sclerotome, myotome and dermatome", "The kidneys"], "answer": 2, "why": "Vertebrae and ribs, skeletal muscle, dermis of the back."}, {"q": "The epithelium of the gut tube derives from:", "options": ["Neural crest", "Endoderm", "Mesoderm", "Ectoderm"], "answer": 1, "why": "The muscle and connective tissue of the gut wall come from splanchnic mesoderm."}, {"q": "The embryonic period (organogenesis) lasts:", "options": ["The whole pregnancy", "Weeks 9-38", "Weeks 1-2", "Weeks 3-8"], "answer": 3, "why": "This is the most sensitive period for major malformations; from week 9 the fetal period is mainly growth."}, {"q": "The fetal component of the placenta is:", "options": ["The myometrium", "The decidua parietalis", "The chorion frondosum", "The decidua basalis"], "answer": 2, "why": "Maternal component = decidua basalis."}, {"q": "The amniotic fluid:", "options": ["Is never swallowed by the fetus", "Has no protective role", "Is produced only by the placenta", "Allows fetal movement and lung development; it is swallowed and replaced by fetal urine"], "answer": 3, "why": "Oligohydramnios can result from renal agenesis; polyhydramnios from oesophageal atresia."}, {"q": "Oligohydramnios can be caused by:", "options": ["Anencephaly", "Oesophageal atresia", "Maternal diabetes", "Bilateral renal agenesis"], "answer": 3, "why": "Fetal urine is the main source of amniotic fluid in later pregnancy."}, {"q": "Physiological umbilical herniation of the midgut:", "options": ["Happens around week 6 and returns by week 10", "Involves the liver only", "Never happens in normal development", "Persists until birth"], "answer": 0, "why": "The midgut rotates 270° anticlockwise around the superior mesenteric artery. Failure of return = omphalocele."}, {"q": "The liver bud arises from:", "options": ["The neural crest", "The yolk sac mesoderm only", "The foregut endoderm (distal part)", "The hindgut"], "answer": 2, "why": "The hepatic diverticulum grows into the septum transversum."}, {"q": "The ventral and dorsal pancreatic buds fuse after:", "options": ["Rotation of the ventral bud behind the duodenum", "Closure of the neural tube", "Separation of the oesophagus", "Return of the midgut"], "answer": 0, "why": "The ventral bud forms the uncinate process and part of the head; abnormal rotation can cause annular pancreas."}, {"q": "Monozygotic twins sharing one chorion and one amnion usually come from splitting at:", "options": ["The 2-cell stage", "The morula stage", "After the formation of the amnion (about days 8-12)", "Before fertilisation"], "answer": 2, "why": "Early splitting (days 0-3) gives two chorions and two amnions; days 4-8 one chorion, two amnions."}]}, {"id": "y1-histo1-sina-mock", "subject": "histo1", "title": "Sina mock exam: Histology", "year": "Practice", "note": "20 new questions written by Sina in the style of the real exam, covering the four basic tissues and the digestive and urinary systems. One answer per question, each with a short explanation.", "questions": [{"q": "The epithelium lining the urinary bladder is:", "options": ["Simple squamous", "Transitional (urothelium)", "Stratified squamous keratinised", "Simple columnar"], "answer": 1, "why": "Urothelium stretches; its umbrella cells protect against urine."}, {"q": "Simple squamous epithelium lines:", "options": ["The small intestine", "Blood vessels (endothelium) and alveoli", "The oesophagus", "The skin"], "answer": 1, "why": "Thin cells allow diffusion and filtration."}, {"q": "The epithelium of the trachea is:", "options": ["Simple cuboidal", "Stratified squamous", "Transitional", "Pseudostratified ciliated columnar with goblet cells"], "answer": 3, "why": "Respiratory epithelium."}, {"q": "Tight junctions (zonula occludens):", "options": ["Seal the space between neighbouring cells", "Link intermediate filaments", "Allow ions to pass between cells", "Anchor cells to the basement membrane"], "answer": 0, "why": "Gap junctions pass ions; desmosomes link intermediate filaments; hemidesmosomes anchor to the basement membrane."}, {"q": "The main cell of connective tissue proper, which makes collagen, is:", "options": ["The adipocyte", "The mast cell", "The plasma cell", "The fibroblast"], "answer": 3, "why": "Mast cells release histamine; plasma cells make antibodies."}, {"q": "Type I collagen is the main collagen of:", "options": ["Hyaline cartilage", "Reticular fibres", "Bone, tendon and skin", "Basement membranes"], "answer": 2, "why": "Type II = cartilage; type III = reticular fibres; type IV = basement membranes."}, {"q": "Hyaline cartilage:", "options": ["Is richly vascularised", "Forms the intervertebral disc annulus", "Is avascular and nourished by diffusion from the perichondrium", "Contains mainly type I collagen"], "answer": 2, "why": "Articular cartilage has no perichondrium. Fibrocartilage (type I collagen) forms the annulus fibrosus."}, {"q": "Elastic cartilage is found in:", "options": ["The pubic symphysis", "The trachea rings", "The articular surfaces", "The external ear and epiglottis"], "answer": 3, "why": "Tracheal rings are hyaline; the pubic symphysis is fibrocartilage."}, {"q": "Osteoclasts:", "options": ["Are trapped in lacunae", "Line the Haversian canals as stem cells", "Are multinucleated cells of monocyte origin that resorb bone", "Build bone matrix"], "answer": 2, "why": "Osteoblasts make osteoid; osteocytes sit in lacunae and communicate by canaliculi."}, {"q": "The functional unit of compact bone is:", "options": ["The sarcomere", "The trabecula", "The lacuna", "The osteon (Haversian system)"], "answer": 3, "why": "Concentric lamellae around a central (Haversian) canal; Volkmann canals run across."}, {"q": "Endochondral ossification forms:", "options": ["The clavicle entirely", "Most long bones, from a cartilage model", "Teeth", "The flat bones of the skull"], "answer": 1, "why": "Intramembranous ossification forms the flat bones of the skull and part of the clavicle."}, {"q": "Neutrophils in a blood smear have:", "options": ["Dark blue granules hiding the nucleus", "A large round nucleus filling the cell", "Large orange-red granules and a bilobed nucleus", "A multilobed (3-5 lobes) nucleus and pale granules"], "answer": 3, "why": "Eosinophils: bilobed with red-orange granules; basophils: dark purple granules."}, {"q": "Skeletal muscle fibres are:", "options": ["Branched, with one central nucleus", "Joined by intercalated discs", "Spindle-shaped and non-striated", "Long, multinucleated, striated, with peripheral nuclei"], "answer": 3, "why": "Cardiac: branched, central nucleus, intercalated discs. Smooth: spindle-shaped, no striations."}, {"q": "The sarcomere extends between:", "options": ["An A band and an I band", "Two M lines", "Two H zones", "Two Z lines (discs)"], "answer": 3, "why": "During contraction the I band and H zone shorten; the A band keeps its length."}, {"q": "Myelin in the central nervous system is formed by:", "options": ["Microglia", "Oligodendrocytes", "Astrocytes", "Schwann cells"], "answer": 1, "why": "One oligodendrocyte myelinates several axons; in the PNS one Schwann cell myelinates one internode."}, {"q": "Nissl bodies in neurons are:", "options": ["Clusters of rough endoplasmic reticulum and ribosomes", "Mitochondria", "Neurofilaments", "Lysosomes"], "answer": 0, "why": "They stain with basic dyes and are absent from the axon hillock."}, {"q": "The muscularis externa of most of the digestive tract has:", "options": ["One layer", "Inner circular and outer longitudinal layers", "Inner longitudinal and outer circular layers", "Three oblique layers everywhere"], "answer": 1, "why": "The stomach adds an inner oblique layer. The myenteric (Auerbach) plexus lies between the two layers."}, {"q": "Paneth cells are found:", "options": ["In the oesophageal glands", "In the colon surface epithelium", "In the gastric pits", "At the base of the intestinal crypts of Lieberkühn"], "answer": 3, "why": "They secrete lysozyme and defensins."}, {"q": "Brunner's glands are characteristic of:", "options": ["The duodenum (submucosa)", "The jejunum", "The colon", "The ileum"], "answer": 0, "why": "They secrete alkaline mucus to neutralise gastric acid."}, {"q": "Podocytes are found in:", "options": ["The loop of Henle", "The collecting duct", "The proximal tubule", "The visceral layer of Bowman's capsule"], "answer": 3, "why": "Their foot processes and filtration slits form part of the glomerular filtration barrier."}]}, {"id": "y1-bacterio1-sina-mock", "subject": "bacterio1", "title": "Sina mock exam: Bacteriology", "year": "Practice", "note": "20 new questions written by Sina in the style of the real exam, covering bacterial structure, genetics, antibiotics and the main pathogens of the course. One answer per question, each with a short explanation.", "questions": [{"q": "Gram-positive bacteria stain purple because they have:", "options": ["A thick peptidoglycan layer that keeps crystal violet", "An outer membrane with LPS", "Mycolic acids", "No cell wall"], "answer": 0, "why": "Gram-negatives have a thin peptidoglycan layer plus an outer membrane with LPS (endotoxin)."}, {"q": "Bacterial endospores:", "options": ["Are killed by boiling for 1 minute", "Are resistant dormant forms (e.g. Bacillus, Clostridium)", "Are found in Gram-negative cocci", "Are a means of reproduction"], "answer": 1, "why": "Autoclaving (121 °C) is needed to destroy them."}, {"q": "Transfer of genes by a bacteriophage is called:", "options": ["Transduction", "Transformation", "Transposition", "Conjugation"], "answer": 0, "why": "Transformation = uptake of free DNA; conjugation = transfer through a pilus (plasmids)."}, {"q": "Endotoxin (LPS):", "options": ["Is heat-labile", "Is part of the outer membrane of Gram-negative bacteria; lipid A is the toxic part", "Is secreted by Gram-positive bacteria", "Is a protein that is easily turned into a toxoid"], "answer": 1, "why": "Exotoxins are secreted proteins and can be made into toxoids; endotoxin is heat-stable."}, {"q": "β-lactam antibiotics act by:", "options": ["Inhibiting cell-wall synthesis (binding penicillin-binding proteins)", "Inhibiting DNA gyrase", "Inhibiting protein synthesis at the 30S subunit", "Disrupting the cell membrane"], "answer": 0, "why": "Aminoglycosides and tetracyclines act on the 30S subunit; fluoroquinolones inhibit DNA gyrase."}, {"q": "Methicillin resistance in Staphylococcus aureus is due to:", "options": ["Loss of porins", "β-lactamase only", "Efflux pumps", "An altered penicillin-binding protein (PBP2a, mecA gene)"], "answer": 3, "why": "PBP2a has low affinity for almost all β-lactams."}, {"q": "Streptococcus pyogenes is:", "options": ["β-haemolytic group A, bacitracin-sensitive", "α-haemolytic, optochin-sensitive", "γ-haemolytic", "A Gram-negative diplococcus"], "answer": 0, "why": "S. pneumoniae is α-haemolytic and optochin-sensitive."}, {"q": "A non-suppurative complication of S. pyogenes pharyngitis is:", "options": ["Scarlet fever", "Acute rheumatic fever", "Necrotising fasciitis", "Impetigo"], "answer": 1, "why": "Rheumatic fever (after pharyngitis) and post-streptococcal glomerulonephritis are immune-mediated sequelae."}, {"q": "The main virulence factor of Streptococcus pneumoniae is:", "options": ["M protein", "Coagulase", "Endotoxin", "Its polysaccharide capsule"], "answer": 3, "why": "The capsule resists phagocytosis; vaccines target capsular polysaccharides."}, {"q": "Haemophilus influenzae grows on chocolate agar because it needs:", "options": ["Cysteine", "Only X factor", "Charcoal", "X factor (haemin) and V factor (NAD)"], "answer": 3, "why": "Hib's polyribosyl-ribitol-phosphate capsule is the target of the conjugate vaccine."}, {"q": "Mycobacterium tuberculosis is identified on a smear by:", "options": ["India ink", "Gram stain (Gram-positive cocci)", "Ziehl-Neelsen stain (acid-fast bacilli)", "Giemsa stain"], "answer": 2, "why": "Mycolic acids make the wall acid-fast."}, {"q": "The classic medium for culturing M. tuberculosis is:", "options": ["MacConkey agar", "Löwenstein-Jensen", "Blood agar", "Thayer-Martin"], "answer": 1, "why": "Growth is slow (3-6 weeks)."}, {"q": "Chlamydia species are:", "options": ["Acid-fast bacilli", "Free-living bacteria", "Obligate intracellular bacteria with elementary and reticulate bodies", "Bacteria without any cell wall"], "answer": 2, "why": "The elementary body is infectious; the reticulate body divides inside the cell."}, {"q": "Bordetella pertussis causes whooping cough mainly through:", "options": ["Spore formation", "Pertussis toxin and adhesins that act on the ciliated respiratory epithelium", "Invasion of the bloodstream", "A polysaccharide capsule"], "answer": 1, "why": "Pertussis toxin raises cAMP (ADP-ribosylates Gi); the paroxysmal stage gives the 'whoop'."}, {"q": "Mycoplasma pneumoniae is not treated by β-lactams because it:", "options": ["Produces β-lactamase", "Has no cell wall", "Is acid-fast", "Has a thick capsule"], "answer": 1, "why": "Macrolides or tetracyclines are used. Its membrane contains sterols."}, {"q": "Enterobacteriaceae are:", "options": ["Gram-negative bacilli, oxidase-negative, that ferment glucose", "Acid-fast", "Gram-positive cocci", "Obligate anaerobes"], "answer": 0, "why": "They also reduce nitrates to nitrites."}, {"q": "A lactose-fermenting, pink colony on MacConkey agar is typical of:", "options": ["Shigella", "Salmonella", "Proteus", "Escherichia coli"], "answer": 3, "why": "Salmonella, Shigella and Proteus do not ferment lactose (pale colonies)."}, {"q": "The most common cause of community urinary tract infection is:", "options": ["Proteus mirabilis", "Escherichia coli (uropathogenic)", "Klebsiella pneumoniae", "Salmonella Typhi"], "answer": 1, "why": "Proteus produces urease (alkaline urine, stones)."}, {"q": "Salmonella Typhi:", "options": ["Does not produce H2S", "Has animal reservoirs", "Infects only humans and causes typhoid fever", "Ferments lactose"], "answer": 2, "why": "Non-typhoidal Salmonella have animal reservoirs and cause gastroenteritis."}, {"q": "Proteus mirabilis is recognised in the laboratory by:", "options": ["Acid-fast staining", "Optochin sensitivity", "Swarming motility on blood agar and strong urease activity", "Need for X and V factors"], "answer": 2, "why": "Urease splits urea into ammonia, giving struvite stones."}]}]);
